#include <iostream>
#include <vector>
using namespace std;

// O(1) - Thời gian hằng số: không phụ thuộc kích thước mảng
int layPhanTuDau(const vector<int>& a) {
    return a[0];
}

// O(log n) - Logarit: tìm kiếm nhị phân, mỗi bước bỏ đi một nửa
int binarySearch(const vector<int>& a, int x) {
    int trai = 0, phai = (int)a.size() - 1;
    while (trai <= phai) {
        int giua = trai + (phai - trai) / 2;
        if (a[giua] == x) return giua;
        if (a[giua] < x) trai = giua + 1;
        else phai = giua - 1;
    }
    return -1;
}

// O(n) - Tuyến tính: duyệt mảng một lần
int timMax(const vector<int>& a) {
    int lonNhat = a[0];
    for (int x : a) if (x > lonNhat) lonNhat = x;
    return lonNhat;
}

// O(n²) - Bậc hai: hai vòng lặp lồng nhau
int demCapTongBangK(const vector<int>& a, int k) {
    int dem = 0;
    for (size_t i = 0; i < a.size(); i++)
        for (size_t j = i + 1; j < a.size(); j++)
            if (a[i] + a[j] == k) dem++;
    return dem;
}

// O(2ⁿ) - Hàm mũ: mỗi lần gọi tách thành 2 lần gọi (Fibonacci đệ quy ngây thơ)
long long fib(int n) {
    return n <= 1 ? n : fib(n - 1) + fib(n - 2);
}

// Bộ nhớ O(n): tạo thêm một mảng cùng kích thước
vector<int> nhanDoi(const vector<int>& a) {
    vector<int> kq;
    kq.reserve(a.size());
    for (int x : a) kq.push_back(x * 2);
    return kq;
}

int main() {
    vector<int> a = {1, 3, 5, 7, 9, 11};
    cout << "O(1)     layPhanTuDau = " << layPhanTuDau(a) << '\n';
    cout << "O(log n) binarySearch(9) = " << binarySearch(a, 9) << '\n';
    cout << "O(n)     timMax = " << timMax(a) << '\n';
    cout << "O(n^2)   demCapTongBangK(12) = " << demCapTongBangK(a, 12) << '\n';
    cout << "O(2^n)   fib(25) = " << fib(25) << '\n';
    cout << "Bộ nhớ O(n): nhanDoi tạo mảng mới " << nhanDoi(a).size() << " phần tử\n";
}

#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>
using namespace std;

// 1. Two Pointers - tìm cặp phần tử có tổng bằng target trên mảng ĐÃ sắp xếp, O(n)
pair<int, int> twoSum(const vector<int>& a, int target) {
    int trai = 0, phai = (int)a.size() - 1;
    while (trai < phai) {
        int tong = a[trai] + a[phai];
        if (tong == target) return {trai, phai};
        if (tong < target) trai++;
        else phai--;
    }
    return {-1, -1};
}

// 2. Sliding Window - tổng lớn nhất của mảng con độ dài k, O(n)
int maxSubarraySum(const vector<int>& a, int k) {
    int tongCuaSo = 0;
    for (int i = 0; i < k; i++) tongCuaSo += a[i];
    int lonNhat = tongCuaSo;
    for (int i = k; i < (int)a.size(); i++) {
        tongCuaSo += a[i] - a[i - k]; // trượt cửa sổ sang phải
        lonNhat = max(lonNhat, tongCuaSo);
    }
    return lonNhat;
}

// 3. Bảng tần suất - ký tự xuất hiện nhiều nhất, O(n)
char kyTuNhieuNhat(const string& s) {
    unordered_map<char, int> dem;
    char kq = '\0';
    int nhieuNhat = 0;
    for (char c : s) {
        if (++dem[c] > nhieuNhat) {
            nhieuNhat = dem[c];
            kq = c;
        }
    }
    return kq;
}

// 4. Prefix Sum - tiền xử lý O(n), mỗi truy vấn tổng đoạn [i..j] chỉ O(1)
struct TongCongDon {
    vector<long long> p;
    explicit TongCongDon(const vector<int>& a) : p(a.size() + 1, 0) {
        for (size_t i = 0; i < a.size(); i++) p[i + 1] = p[i] + a[i];
    }
    long long tong(int i, int j) const { return p[j + 1] - p[i]; }
};

int main() {
    auto [i, j] = twoSum({1, 2, 4, 7, 11, 15}, 15);
    cout << "twoSum(15): vị trí " << i << " và " << j << '\n';
    cout << "maxSubarraySum(k = 3): " << maxSubarraySum({2, 1, 5, 1, 3, 2}, 3) << '\n';
    cout << "Ký tự nhiều nhất trong \"banana\": " << kyTuNhieuNhat("banana") << '\n';
    TongCongDon t({3, 1, 4, 1, 5, 9});
    cout << "Tổng đoạn [1..4]: " << t.tong(1, 4) << '\n';
}

#include <iostream>
#include <vector>
#include <string>
