using namespace std;

// 1. Bubble Sort - O(n²), ổn định: đổi chỗ cặp kề nhau, dừng sớm nếu một vòng không đổi gì
void bubbleSort(vector<int>& a) {
    int n = a.size();
    for (int i = 0; i < n - 1; i++) {
        bool daDoi = false;
        for (int j = 0; j < n - 1 - i; j++) {
            if (a[j] > a[j + 1]) {
                swap(a[j], a[j + 1]);
                daDoi = true;
            }
        }
        if (!daDoi) break; // mảng đã sắp xếp: O(n) trong trường hợp tốt nhất
    }
}

// 2. Selection Sort - O(n²), không ổn định: mỗi vòng chọn phần tử nhỏ nhất đưa lên đầu
void selectionSort(vector<int>& a) {
    int n = a.size();
    for (int i = 0; i < n - 1; i++) {
        int nhoNhat = i;
        for (int j = i + 1; j < n; j++) if (a[j] < a[nhoNhat]) nhoNhat = j;
        if (nhoNhat != i) swap(a[i], a[nhoNhat]);
    }
}

// 3. Insertion Sort - O(n²), ổn định, gần O(n) khi mảng gần như đã sắp xếp
void insertionSort(vector<int>& a) {
    for (int i = 1; i < (int)a.size(); i++) {
        int hienTai = a[i];
        int j = i - 1;
        while (j >= 0 && a[j] > hienTai) {
            a[j + 1] = a[j]; // đẩy phần tử lớn hơn sang phải
            j--;
        }
        a[j + 1] = hienTai;
    }
}

// 4. Shell Sort - Insertion Sort với khoảng cách gap giảm dần: n/2, n/4, ..., 1
void shellSort(vector<int>& a) {
    int n = a.size();
    for (int gap = n / 2; gap > 0; gap /= 2) {
        for (int i = gap; i < n; i++) {
            int hienTai = a[i];
            int j = i;
            while (j >= gap && a[j - gap] > hienTai) {
                a[j] = a[j - gap];
                j -= gap;
            }
            a[j] = hienTai;
        }
    }
}

void in(const string& ten, const vector<int>& a) {
    cout << ten;
    for (int x : a) cout << x << ' ';
    cout << '\n';
}

struct SinhVien { string ten; int diem; };

int main() {
    const vector<int> goc = {29, 10, 14, 37, 13, 5, 88, 1};
    vector<int> a = goc; bubbleSort(a);    in("Bubble   : ", a);
    a = goc;             selectionSort(a); in("Selection: ", a);
    a = goc;             insertionSort(a); in("Insertion: ", a);
    a = goc;             shellSort(a);     in("Shell    : ", a);

    // Trong thực tế: dùng thư viện chuẩn <algorithm>
    a = goc;
    sort(a.begin(), a.end(), greater<int>()); // giảm dần
    in("std::sort giảm dần: ", a);

    vector<SinhVien> lop = {{"An", 8}, {"Bình", 9}, {"Chi", 8}, {"Dũng", 9}};
    stable_sort(lop.begin(), lop.end(), [](const SinhVien& x, const SinhVien& y) {
        return x.diem > y.diem; // dùng > chứ không dùng >= (strict weak ordering)
    });
    cout << "stable_sort theo điểm: ";
    for (const auto& sv : lop) cout << sv.ten << '(' << sv.diem << ") ";
    cout << '\n';
