using namespace std;

// 1. Merge Sort - luôn O(n log n), ổn định, dùng mảng phụ O(n)
void tron(vector<int>& a, int trai, int giua, int phai, vector<int>& tam) {
    int i = trai, j = giua + 1, k = trai;
    while (i <= giua && j <= phai) tam[k++] = (a[i] <= a[j]) ? a[i++] : a[j++]; // <= giữ thứ tự phần tử bằng nhau
    while (i <= giua) tam[k++] = a[i++];
    while (j <= phai) tam[k++] = a[j++];
    for (int t = trai; t <= phai; t++) a[t] = tam[t];
}
void mergeSort(vector<int>& a, int trai, int phai, vector<int>& tam) {
    if (trai >= phai) return;
    int giua = trai + (phai - trai) / 2;
    mergeSort(a, trai, giua, tam);
    mergeSort(a, giua + 1, phai, tam);
    tron(a, trai, giua, phai, tam);
}
void mergeSort(vector<int>& a) {
    vector<int> tam(a.size());
    if (!a.empty()) mergeSort(a, 0, (int)a.size() - 1, tam);
}

// 2. Quick Sort tại chỗ - phân hoạch Lomuto, pivot ngẫu nhiên, trung bình O(n log n)
mt19937 rng(2024);
void quickSort(vector<int>& a, int dau, int cuoi) {
    if (dau >= cuoi) return;
    int r = uniform_int_distribution<int>(dau, cuoi)(rng);
    swap(a[r], a[cuoi]); // đưa pivot ngẫu nhiên về cuối
    int pivot = a[cuoi];
    int i = dau;         // a[dau..i-1] luôn < pivot
    for (int j = dau; j < cuoi; j++) if (a[j] < pivot) swap(a[i++], a[j]);
    swap(a[i], a[cuoi]); // pivot về đúng chỗ
    quickSort(a, dau, i - 1);
    quickSort(a, i + 1, cuoi);
}
void quickSort(vector<int>& a) { quickSort(a, 0, (int)a.size() - 1); }

// 3. Heap Sort - luôn O(n log n), bộ nhớ O(1)
void vunDong(vector<int>& a, int i, int kichThuoc) {
    while (true) {
        int trai = 2 * i + 1, phai = 2 * i + 2, lonNhat = i;
        if (trai < kichThuoc && a[trai] > a[lonNhat]) lonNhat = trai;
        if (phai < kichThuoc && a[phai] > a[lonNhat]) lonNhat = phai;
        if (lonNhat == i) return;
        swap(a[i], a[lonNhat]);
        i = lonNhat;
    }
}
void heapSort(vector<int>& a) {
    int n = a.size();
    for (int i = n / 2 - 1; i >= 0; i--) vunDong(a, i, n); // dựng max-heap
    for (int cuoi = n - 1; cuoi > 0; cuoi--) {
        swap(a[0], a[cuoi]); // phần tử lớn nhất về cuối
        vunDong(a, 0, cuoi);
    }
}

// 4. Counting Sort - O(n + k) cho số nguyên trong khoảng 0..k
void countingSort(vector<int>& a) {
    if (a.empty()) return;
    int k = *max_element(a.begin(), a.end());
    vector<int> dem(k + 1, 0);
    for (int x : a) dem[x]++;
    int vt = 0;
    for (int giaTri = 0; giaTri <= k; giaTri++)
        while (dem[giaTri]-- > 0) a[vt++] = giaTri;
}

// 5. Radix Sort (LSD, cơ số 10) - mỗi lượt là một Counting Sort ổn định theo một chữ số
void radixSort(vector<int>& a) {
    if (a.empty()) return;
    int lonNhat = *max_element(a.begin(), a.end());
    vector<int> ra(a.size());
    for (long long hang = 1; lonNhat / hang > 0; hang *= 10) {
        int dem[10] = {0};
        for (int x : a) dem[(x / hang) % 10]++;
        for (int d = 1; d < 10; d++) dem[d] += dem[d - 1];  // cộng dồn -> vị trí kết thúc của mỗi chữ số
        for (int i = (int)a.size() - 1; i >= 0; i--)        // duyệt ngược để giữ ổn định
            ra[--dem[(a[i] / hang) % 10]] = a[i];
        a = ra;
    }
}

// 6. Bucket Sort - số thực trong [0, 1), phân bố đều
void bucketSort(vector<double>& a) {
    int n = a.size();
    if (n == 0) return;
    vector<vector<double>> xo(n);
    for (double x : a) xo[min(n - 1, (int)(x * n))].push_back(x);
    int vt = 0;
    for (auto& mot : xo) {
        sort(mot.begin(), mot.end());
        for (double x : mot) a[vt++] = x;
    }
}

template <typename T>
void in(const string& ten, const vector<T>& a) {
    cout << ten;
    for (const T& x : a) cout << x << ' ';
    cout << '\n';
}

int main() {
    const vector<int> goc = {29, 10, 14, 37, 13, 5, 88, 1};
    vector<int> a = goc; mergeSort(a); in("Merge   : ", a);
    a = goc;             quickSort(a); in("Quick   : ", a);
    a = goc;             heapSort(a);  in("Heap    : ", a);
    vector<int> diem = {3, 0, 2, 3, 1, 0, 2};
    countingSort(diem); in("Counting: ", diem);
    vector<int> so = {170, 45, 75, 90, 802, 24, 2, 66};
    radixSort(so); in("Radix   : ", so);
    vector<double> thuc = {0.42, 0.32, 0.23, 0.52, 0.25, 0.47, 0.51};
    bucketSort(thuc); in("Bucket  : ", thuc);
}

