using namespace std;

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int v, ListNode* n = nullptr) : val(v), next(n) {}
};

// Đảo ngược danh sách liên kết - O(n) thời gian, O(1) bộ nhớ
ListNode* reverseList(ListNode* head) {
    ListNode* truoc = nullptr;
    ListNode* hienTai = head;
    while (hienTai) {
        ListNode* sau = hienTai->next;
        hienTai->next = truoc;
        truoc = hienTai;
        hienTai = sau;
    }
    return truoc;
}

// Phát hiện chu trình (thuật toán Floyd: con trỏ chậm & nhanh)
bool hasCycle(ListNode* head) {
    ListNode *cham = head, *nhanh = head;
    while (nhanh && nhanh->next) {
        cham = cham->next;
        nhanh = nhanh->next->next;
        if (cham == nhanh) return true;
    }
    return false;
}

// Stack - kiểm tra chuỗi ngoặc hợp lệ
bool isValid(const string& s) {
    stack<char> st;
    unordered_map<char, char> moTuongUng = {{')', '('}, {']', '['}, {'}', '{'}};
    for (char c : s) {
        if (c == '(' || c == '[' || c == '{') st.push(c);
        else {
            if (st.empty() || st.top() != moTuongUng[c]) return false;
            st.pop();
        }
    }
    return st.empty();
}

void inDanhSach(ListNode* head) {
    for (; head; head = head->next) cout << head->val << (head->next ? " -> " : "\n");
}

void giaiPhong(ListNode* head) {
    while (head) {
        ListNode* sau = head->next;
        delete head;
        head = sau;
    }
}

int main() {
    ListNode* ds = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(4))));
    inDanhSach(ds);
    ds = reverseList(ds);
    inDanhSach(ds);
    cout << boolalpha << "Có chu trình? " << hasCycle(ds) << '\n';
    cout << "\"({[]})\" hợp lệ? " << isValid("({[]})") << '\n';
    cout << "\"(]\" hợp lệ? " << isValid("(]") << '\n';

