// Two Sum với unordered_map - O(n)
pair<int, int> twoSum(const vector<int>& a, int target) {
    unordered_map<int, int> viTri; // giá trị -> chỉ số
    for (int i = 0; i < (int)a.size(); i++) {
        auto it = viTri.find(target - a[i]);
        if (it != viTri.end()) return {it->second, i};
        viTri[a[i]] = i;
    }
    return {-1, -1};
}

// Nhóm các từ đảo chữ (Group Anagrams): chuỗi đã sắp xếp ký tự làm khóa
vector<vector<string>> groupAnagrams(const vector<string>& tu) {
    unordered_map<string, vector<string>> nhom;
    for (const string& s : tu) {
        string khoa = s;
        sort(khoa.begin(), khoa.end());
        nhom[khoa].push_back(s);
    }
    vector<vector<string>> kq;
    for (auto& [khoa, ds] : nhom) kq.push_back(ds);
    return kq;
}

// LRU Cache - get/put O(1): std::list giữ thứ tự dùng + unordered_map trỏ thẳng vào nút
class LRUCache {
    int sucChua;
    list<pair<int, int>> dsDung; // đầu danh sách = vừa dùng gần nhất
    unordered_map<int, list<pair<int, int>>::iterator> viTri;
public:
    explicit LRUCache(int c) : sucChua(c) {}
    int get(int key) {
        auto it = viTri.find(key);
        if (it == viTri.end()) return -1;
        dsDung.splice(dsDung.begin(), dsDung, it->second); // đưa lên đầu, O(1)
        return it->second->second;
    }
    void put(int key, int value) {
        auto it = viTri.find(key);
        if (it != viTri.end()) {
            it->second->second = value;
            dsDung.splice(dsDung.begin(), dsDung, it->second);
            return;
        }
        if ((int)dsDung.size() == sucChua) { // đầy: bỏ phần tử lâu nhất chưa dùng
            viTri.erase(dsDung.back().first);
            dsDung.pop_back();
        }
        dsDung.emplace_front(key, value);
        viTri[key] = dsDung.begin();
    }
};

int main() {
    auto [i, j] = twoSum({2, 7, 11, 15}, 9);
    cout << "twoSum(9): " << i << ", " << j << '\n';
    for (const auto& nhom : groupAnagrams({"eat", "tea", "tan", "ate", "nat", "bat"})) {
        for (const auto& s : nhom) cout << s << ' ';
        cout << "| ";
    }
    cout << '\n';
    LRUCache cache(2);
    cache.put(1, 1);
    cache.put(2, 2);
    cout << "get(1) = " << cache.get(1) << '\n'; // 1
    cache.put(3, 3);                              // đầy: bỏ key 2
    cout << "get(2) = " << cache.get(2) << '\n'; // -1
}

#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

struct TreeNode {
    int val;
    TreeNode* left = nullptr;
    TreeNode* right = nullptr;
    explicit TreeNode(int v) : val(v) {}
};

// Chèn vào cây tìm kiếm nhị phân (BST): nhỏ hơn sang trái, lớn hơn sang phải
TreeNode* chen(TreeNode* goc, int x) {
    if (!goc) return new TreeNode(x);
    if (x < goc->val) goc->left = chen(goc->left, x);
    else goc->right = chen(goc->right, x);
    return goc;
}

// Duyệt DFS Inorder (Trái -> Gốc -> Phải): cho thứ tự tăng dần trên BST
void inorder(TreeNode* goc, vector<int>& kq) {
    if (!goc) return;
    inorder(goc->left, kq);
    kq.push_back(goc->val);
    inorder(goc->right, kq);
}

// Duyệt BFS theo từng tầng (Level Order Traversal)
vector<vector<int>> levelOrder(TreeNode* goc) {
    vector<vector<int>> kq;
    if (!goc) return kq;
    queue<TreeNode*> q;
    q.push(goc);
    while (!q.empty()) {
        int soNut = q.size();
        vector<int> tang;
        for (int i = 0; i < soNut; i++) {
            TreeNode* nut = q.front();
            q.pop();
            tang.push_back(nut->val);
            if (nut->left) q.push(nut->left);
            if (nut->right) q.push(nut->right);
        }
        kq.push_back(tang);
    }
    return kq;
}

// Độ sâu tối đa của cây
int maxDepth(TreeNode* goc) {
    if (!goc) return 0;
    return 1 + max(maxDepth(goc->left), maxDepth(goc->right));
}

void giaiPhong(TreeNode* goc) {
    if (!goc) return;
    giaiPhong(goc->left);
    giaiPhong(goc->right);
    delete goc;
}

int main() {
    TreeNode* goc = nullptr;
    for (int x : {8, 3, 10, 1, 6, 14, 4, 7}) goc = chen(goc, x);
    vector<int> tangDan;
    inorder(goc, tangDan);
    cout << "Inorder (tăng dần): ";
    for (int x : tangDan) cout << x << ' ';
    cout << "\nTheo từng tầng: ";
    for (const auto& tang : levelOrder(goc)) {
        cout << '[';
        for (size_t i = 0; i < tang.size(); i++) cout << tang[i] << (i + 1 < tang.size() ? "," : "");
        cout << "] ";
    }
    cout << "\nĐộ sâu: " << maxDepth(goc) << '\n';
    giaiPhong(goc);
}

#include <iostream>
