// BFS: đường đi ít cạnh nhất giữa hai đỉnh
vector<int> duongNganNhat(const DoThi& g, int batDau, int dich) {
    vector<int> cha(g.size(), -1);
    vector<bool> daTham(g.size(), false);
    queue<int> q;
    q.push(batDau);
    daTham[batDau] = true;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        if (u == dich) break;
        for (int v : g[u]) {
            if (!daTham[v]) {
                daTham[v] = true;
                cha[v] = u;
                q.push(v);
            }
        }
    }
    if (!daTham[dich]) return {};
    vector<int> duong;
    for (int v = dich; v != -1; v = cha[v]) duong.push_back(v);
    reverse(duong.begin(), duong.end());
    return duong;
}

// DFS: đếm số thành phần liên thông
void dfs(const DoThi& g, int u, vector<bool>& daTham) {
    daTham[u] = true;
    for (int v : g[u]) if (!daTham[v]) dfs(g, v, daTham);
}
int demThanhPhan(const DoThi& g) {
    vector<bool> daTham(g.size(), false);
    int dem = 0;
    for (int u = 0; u < (int)g.size(); u++) {
        if (!daTham[u]) {
            dfs(g, u, daTham);
            dem++;
        }
    }
    return dem;
}

// Topo Sort (thuật toán Kahn): thứ tự làm việc khi có ràng buộc "phải làm A trước B"
vector<int> topoSort(const DoThi& g) {
    vector<int> bacVao(g.size(), 0);
    for (const auto& ke : g) for (int v : ke) bacVao[v]++;
    queue<int> q;
    for (int u = 0; u < (int)g.size(); u++) if (bacVao[u] == 0) q.push(u);
    vector<int> thuTu;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        thuTu.push_back(u);
        for (int v : g[u]) if (--bacVao[v] == 0) q.push(v);
    }
    if (thuTu.size() != g.size()) return {}; // có chu trình: không tồn tại thứ tự
    return thuTu;
}

int main() {
    DoThi g = taoDoThi(6, {{0, 1}, {1, 2}, {0, 3}, {3, 2}, {4, 5}});
    cout << "Đường ngắn nhất 0 -> 2: ";
    for (int v : duongNganNhat(g, 0, 2)) cout << v << ' ';
    cout << "\nSố thành phần liên thông: " << demThanhPhan(g) << '\n';
    DoThi monHoc = taoDoThi(4, {{0, 1}, {0, 2}, {1, 3}, {2, 3}}, true);
    cout << "Thứ tự học các môn (topo): ";
    for (int v : topoSort(monHoc)) cout << v << ' ';
    cout << '\n';
}

