// 1D DP: leo cầu thang, mỗi bước 1 hoặc 2 bậc
long long climbStairs(int n) {
    if (n <= 2) return n;
    long long truoc2 = 1, truoc1 = 2;
    for (int i = 3; i <= n; i++) {
        long long hienTai = truoc1 + truoc2;
        truoc2 = truoc1;
        truoc1 = hienTai;
    }
    return truoc1;
}

// 1D DP: đổi tiền với số đồng xu ít nhất (Coin Change)
int coinChange(const vector<int>& xu, int soTien) {
    const int VO_CUC = INT_MAX;
    vector<int> dp(soTien + 1, VO_CUC);
    dp[0] = 0;
    for (int i = 1; i <= soTien; i++)
        for (int c : xu)
            if (c <= i && dp[i - c] != VO_CUC) dp[i] = min(dp[i], dp[i - c] + 1); // kiểm tra để không tràn số
    return dp[soTien] == VO_CUC ? -1 : dp[soTien];
}

// 2D DP: chuỗi con chung dài nhất (Longest Common Subsequence)
int lcs(const string& a, const string& b) {
    int m = a.size(), n = b.size();
    vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));
    for (int i = 1; i <= m; i++)
        for (int j = 1; j <= n; j++)
            dp[i][j] = (a[i - 1] == b[j - 1]) ? dp[i - 1][j - 1] + 1 : max(dp[i - 1][j], dp[i][j - 1]);
    return dp[m][n];
}

int main() {
    cout << "climbStairs(10) = " << climbStairs(10) << '\n';
    cout << "coinChange({1, 2, 5}, 11) = " << coinChange({1, 2, 5}, 11) << '\n';
    cout << "coinChange({2}, 3) = " << coinChange({2}, 3) << '\n';
    cout << "lcs(\"abcde\", \"ace\") = " << lcs("abcde", "ace") << '\n';
}

