// Min Heap tự cài đặt: phần tử nhỏ nhất luôn ở gốc
class MinHeap {
    vector<int> d;
    void dayLen(int i) {
        while (i > 0) {
            int cha = (i - 1) / 2;
            if (d[cha] <= d[i]) break;
            swap(d[cha], d[i]);
            i = cha;
        }
    }
    void dayXuong(int i) {
        int n = d.size();
        while (2 * i + 1 < n) {
            int con = 2 * i + 1;
            if (con + 1 < n && d[con + 1] < d[con]) con++;
            if (d[i] <= d[con]) break;
            swap(d[i], d[con]);
            i = con;
        }
    }
public:
    int size() const { return d.size(); }
    void push(int x) {
        d.push_back(x);
        dayLen(d.size() - 1);
    }
    int pop() {
        if (d.empty()) throw out_of_range("heap rỗng");
        int nhoNhat = d[0];
        d[0] = d.back();
        d.pop_back();
        if (!d.empty()) dayXuong(0);
        return nhoNhat;
    }
};

// Trie (cây tiền tố) cho chữ thường a-z: phục vụ gợi ý từ khóa (autocomplete)
class Trie {
    struct Nut {
        array<unique_ptr<Nut>, 26> con;
        bool ketThuc = false;
    };
    Nut goc;
    const Nut* tim(const string& s) const {
        const Nut* nut = &goc;
        for (char c : s) {
            nut = nut->con[c - 'a'].get();
            if (!nut) return nullptr;
        }
        return nut;
    }
public:
    void insert(const string& tu) {
        Nut* nut = &goc;
        for (char c : tu) {
            auto& tiep = nut->con[c - 'a'];
            if (!tiep) tiep = make_unique<Nut>();
            nut = tiep.get();
        }
        nut->ketThuc = true;
    }
    bool search(const string& tu) const {
        const Nut* nut = tim(tu);
        return nut && nut->ketThuc;
    }
    bool startsWith(const string& tienTo) const { return tim(tienTo) != nullptr; }
};

// Segment Tree: tính tổng đoạn và cập nhật một phần tử, đều O(log n)
class SegmentTree {
    int n;
    vector<long long> cay;
    void xay(const vector<int>& a, int nut, int l, int r) {
        if (l == r) {
            cay[nut] = a[l];
            return;
        }
        int m = (l + r) / 2;
        xay(a, 2 * nut, l, m);
        xay(a, 2 * nut + 1, m + 1, r);
        cay[nut] = cay[2 * nut] + cay[2 * nut + 1];
    }
    void capNhat(int nut, int l, int r, int i, int giaTri) {
        if (l == r) {
            cay[nut] = giaTri;
            return;
        }
        int m = (l + r) / 2;
        if (i <= m) capNhat(2 * nut, l, m, i, giaTri);
        else capNhat(2 * nut + 1, m + 1, r, i, giaTri);
        cay[nut] = cay[2 * nut] + cay[2 * nut + 1];
    }
    long long tong(int nut, int l, int r, int ql, int qr) const {
        if (qr < l || r < ql) return 0;
        if (ql <= l && r <= qr) return cay[nut];
        int m = (l + r) / 2;
        return tong(2 * nut, l, m, ql, qr) + tong(2 * nut + 1, m + 1, r, ql, qr);
    }
public:
    explicit SegmentTree(const vector<int>& a) : n(a.size()), cay(4 * a.size(), 0) {
        if (n) xay(a, 1, 0, n - 1);
    }
    void capNhat(int i, int giaTri) { capNhat(1, 0, n - 1, i, giaTri); }
    long long tong(int l, int r) const { return tong(1, 0, n - 1, l, r); }
};

int main() {
    MinHeap h;
    for (int x : {5, 3, 8, 1, 9, 2}) h.push(x);
    cout << "MinHeap lấy ra lần lượt: ";
    while (h.size()) cout << h.pop() << ' ';
    cout << '\n';

    priority_queue<int, vector<int>, greater<int>> pq; // heap có sẵn của C++
    for (int x : {5, 3, 8}) pq.push(x);
    cout << "priority_queue (min) top = " << pq.top() << '\n';

    Trie t;
    for (const string& tu : {"code", "coder", "coding", "data"}) t.insert(tu);
    cout << boolalpha << "search(\"coder\") = " << t.search("coder")
         << ", search(\"cod\") = " << t.search("cod")
         << ", startsWith(\"cod\") = " << t.startsWith("cod") << '\n';

    SegmentTree st({2, 4, 5, 7, 8, 9});
    cout << "Tổng đoạn [1..3] = " << st.tong(1, 3) << '\n';
    st.capNhat(2, 10);
    cout << "Sau khi đặt a[2] = 10: tổng đoạn [1..3] = " << st.tong(1, 3) << '\n';
}

