// Mẫu: Gộp các khoảng bị chồng nhau (Merge Intervals) - O(n log n)
vector<pair<int, int>> gopKhoang(vector<pair<int, int>> ds) {
    if (ds.empty()) return {};
    sort(ds.begin(), ds.end()); // sắp theo điểm bắt đầu
    vector<pair<int, int>> kq = {ds[0]};
    for (size_t i = 1; i < ds.size(); i++) {
        if (ds[i].first <= kq.back().second) kq.back().second = max(kq.back().second, ds[i].second);
        else kq.push_back(ds[i]);
    }
    return kq;
}

struct ListNode {
    int val;
    ListNode* next;
};

// Mẫu: Con trỏ nhanh & chậm - tìm nút ở giữa danh sách liên kết
ListNode* timGiua(ListNode* head) {
    ListNode *cham = head, *nhanh = head;
    while (nhanh && nhanh->next) {
        cham = cham->next;
        nhanh = nhanh->next->next;
    }
    return cham;
}

